+using System.ComponentModel;
+using System.Net.Http.Json;
+using System.Text.Json;
+using Microsoft.Extensions.Logging;
+using ModelContextProtocol.Server;
+
+namespace McpServer.Tools;
+
+[McpServerToolType]
+public sealed class FetchDataTool
+{
+    [McpServerTool("fetch_data"), Description("Fetches data from an external API endpoint.")]
+    public static async Task<string> FetchDataAsync(
+        IHttpClientFactory httpClientFactory,
+        ILogger<FetchDataTool> logger,
+        [Description("The API path to fetch (e.g. \"users/1\").")] string path)
+    {
+        logger.LogInformation("Fetching external API: {Path}", path);
+
+        using var client = httpClientFactory.CreateClient("ExternalApi");
+
+        try
+        {
+            var response = await client.GetAsync(path);
+            response.EnsureSuccessStatusCode();
+
+            var json = await response.Content.ReadFromJsonAsync<JsonElement>();
+            var result = JsonSerializer.Serialize(json, new JsonSerializerOptions { WriteIndented = true });
+
+            logger.LogInformation("Successfully fetched {Bytes} bytes from {Path}", result.Length, path);
+            return result;
+        }
+        catch (HttpRequestException ex)
+        {
+            logger.LogError(ex, "HTTP request to {Path} failed", path);
+            return $"Error fetching data: {ex.Message}";
